insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('shuki','שוקי','שנתיים ו-5 חודשים','מחפש את הבית שמעולם לא היה לו','הסיפור של שוקי התחיל בפברואר 2024. בחורה עם לב ענק הבחינה בו משוטט יחד עם אחותו שירלי בשדות הפתוחים שליד אבו גוש. שוקי היה אז גור קטן בן שלושה חודשים בלבד, רעב ורועד מקור באזור מבודד. מזלו השתנה כשאותה בחורה לא נשארה אדישה, יצרה קשר מיידי עם העמותה וביקשה להציל אותו ואת אחותו.

מאותו גור שברירי, שוקי צמח להיות הכלב הכי חמוד בארץ – כדור של אנרגיה חיובית שפשוט מאוהב באנשים. הוא כלב שובב ושמח, מלא שמחת חיים, ואין לנו ספק שהוא יהיה החבר הכי טוב וייהנה מאוד בחברת ילדים ובני נוער.

לשוקי יש תחביב מתוק במיוחד: הוא הכי אוהב בעולם להתפלש בערימות של מצעים ומגבות עם ריח נקי של כביסה. נראה שבכל פעם שהוא עוצם עיניים בתוך הבד הרך, הוא חולם על הבית שמעולם לא היה לו – בית אמיתי עם משפחה, ריח של נקי ופינה חמה ובטוחה משלו.

שוקי מחכה להתחלה חדשה, ובינתיים הוא זקוק לכם. בחרו לתמוך בשוקי ועזרו לנו להעניק לו את החום והביטחון עד שימצא את הבית המושלם עבורו.','/assets/img/dog-shuki-1.jpg',array['/assets/img/dog-shuki-1.jpg','/assets/img/dog-shuki-2.jpg','/assets/img/dog-shuki-3.jpg','/assets/img/dog-shuki-4.jpg','/assets/img/dog-shuki-5.jpg','/assets/img/dog-shuki-6.jpg','/assets/img/dog-shuki-7.jpg']::text[],true,0);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('bobi','בובי','שנה וחצי','הריצה אל החיים','בובי הוא הרוח החופשית של בית המחסה. אין דבר שמשמח אותו יותר מלרוץ משוחרר בשדות הפתוחים, להרגיש את הרוח באוזניים ופשוט להיות הוא. כשמסתכלים עליו רץ, קשה להאמין שרק לפני זמן קצר הוא כמעט איבד את הכל.

ביוני 2025, כשהיה רק בן שלושה חודשים, בובי עמד שניות ספורות לפני "זריקת המוות". הוא זוהה ככלב בר חסר סיכוי לאימוץ, כזה שאין לו עתיד בחברת בני אדם. אבל העמותה לא ויתרה על הגור הקטן והחליטה לקלוט אותו לבית המחסה.

בזכות עבודה מסורה וסבלנית של מתנדבים מקסימים, קרה הבלתי ייאמן: ה"כלב חסר הסיכוי" הפך לכלב מתוק וחברותי להפליא. הוא אמנם נשאר קצת פחדן וזהיר, אבל הוא ללא ספק אחד הכלבים הכי חמודים בארץ.

בובי זקוק לכם כדי להמשיך לרוץ אל עבר עתיד טוב יותר. בחרו לתמוך בבובי ועזרו לנו להעניק לו את הביטחון והאהבה שהוא זקוק להם כדי להמשיך להיפתח לעולם.','/assets/img/dog-bobi-4.jpg',array['/assets/img/dog-bobi-4.jpg','/assets/img/dog-bobi-1.jpg','/assets/img/dog-bobi-2.jpg','/assets/img/dog-bobi-3.jpg','/assets/img/dog-bobi-5.jpg']::text[],false,1);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('laura','לורה','3 שנים וחצי','מהפחד העמוק אל השכשוך בבריכה','לורה היא ללא ספק חובבת המים המושבעת של בית המחסה. אין דבר שמשמח אותה יותר מאשר לקפוץ בהתלהבות לתוך הבריכה שלנו בקיץ, או לחגוג בתוך שלוליות החורף בחוץ. כשרואים אותה נהנית מהחופש הזה, קשה לדמיין את הכלבה המפוחדת והסגורה שהיא הייתה פעם.

לורה הגיעה אלינו באוגוסט 2023, לאחר שנלקחה לכלבייה זמנית. שם, מרוב אימה וחוסר אונים, היא הסתתרה בתוך "כלוב בתוך כלוב", מנסה להיעלם מהעולם ולא נתנה לאיש להתקרב. אבל אצלנו, בזכות המון סבלנות ושקט, לורה החלה לפרוח. היא הפכה לכלבה נפלאה עם פרווה רכה שפשוט מזמינה ליטוף, אם כי כנסיכה אמיתית – היא שומרת על הגבולות שלה ולא תיתן לכל אחד לגעת בה מיד.

לורה מצאה אצלנו את הביטחון לקפוץ למים, ועכשיו היא זקוקה לכם כדי להמשיך לפרוח. בחרו לתמוך בלורה ועזרו לנו לספק לה את המרחב המוגן והאוהב שמגיע לה.','/assets/img/dog-laura-2.jpg',array['/assets/img/dog-laura-2.jpg','/assets/img/dog-laura-1.jpg','/assets/img/dog-laura-4.jpg','/assets/img/ba-laura-before.jpg','/assets/img/ba-laura-after.jpg']::text[],false,2);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('pil','פיל','שנתיים','הענק עם הלב של גור קטן','פיל הוא התגלמות המושג "תינוק מגודל". התחביב האהוב עליו בעולם? לשבת בנינוחות על כיסא (גם אם הוא קצת קטן למידותיו) ולחלום חלומות בהקיץ. כשמסתכלים עליו מהצד, נראה שהוא בטוח שהוא עדיין גור קטן שיכול להתכרבל לכל אחד בחיק.

פיל הגיע אלינו באוקטובר 2024, כאחד משמונה גורים שהצלנו יחד. כבר אז, כשהיה רק גור, הוא היה גדול פי שניים מאחיו, אבל באופיו הוא היה – ונשאר – הכי תינוקי מכולם. הוא המשיך לגדול ולגדול, ומהר מאוד המתנדבים המוקסמים העניקו לו את שם החיבה "פיל". פיל הוא כלב חמוד להפליא שפשוט לא מודע לממדים המרשימים שלו, והוא מחלק אהבה בעוצמות של ענק.

פיל זקוק לכם כדי להמשיך לחלום בגדול. בחרו לתמוך בענק העדין שלנו ועזרו לנו לספק לו את כל המרחב והתזונה שהוא זקוק להם כדי להישאר התינוק המאושר של כולנו.','/assets/img/dog-pil-1.jpg',array['/assets/img/dog-pil-1.jpg','/assets/img/dog-pil-2.jpg','/assets/img/dog-pil-3.jpg','/assets/img/dog-pil-4.jpg','/assets/img/dog-pil-5.jpg','/assets/img/dog-pil-6.jpg']::text[],true,3);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('gili','גילי','4 שנים','האריה השומר של בית המחסה','גילי הוא הרבה יותר מכלב; הוא אריה בדמות רועה גרמני. יש לו נוכחות של מלך – אצילית, שקטה ובטוחה. הוא המנהיג של הלהקה שלנו, כזה שלא צריך להשמיע קול כדי שיכבדו אותו. אבל למרות המראה העוצמתי והמרשים, יש לו חולשה אחת קטנה ומתוקה: הוא פשוט משוגע על כדורים. ברגע שיש לו כדור, ה"אריה" הופך לגור המאושר בתבל.

הסיפור של גילי התחיל בדצמבר 2022. הוא הופיע לפתע בגינת כלבים בירושלים ונלקח להסגר, שם מצאנו אותו והחלטנו שהוא חייב להגיע אלינו. מהרגע הראשון הוא הפגין חברותיות יוצאת דופן עם כל הכלבים, והפך למנהיג שמרגיע את כולם בנוכחותו.

כשיוצאים עם גילי לטיול, מבינים מהי נאמנות של אריה. הוא שומר על מי שמטייל איתו בנחישות, הולך לצידו בגאווה ולא מסיר ממנו עין. הוא כלב שצריך אדם אחד לסמוך עליו, וברגע שהוא מוצא אותו – הוא יהיה השומר והחבר הכי נאמן בעולם.

גילי מחכה לאדם שיזכה בלב של אריה. בחרו לתמוך בגילי ועזרו לנו להעניק למנהיג המיוחד שלנו את כל מה שהוא זקוק לו עד שימצא את הממלכה הקבועה שלו.','/assets/img/dog-gili-2.jpg',array['/assets/img/dog-gili-2.jpg','/assets/img/dog-gili-1.jpg','/assets/img/dog-gili-3.jpg','/assets/img/dog-gili-4.jpg']::text[],true,4);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('junior','ג''וניור','5 שנים ו-8 חודשים','המלך של בית המחסה','ג''וניור הוא כלב יפה תואר עם נוכחות שאי אפשר להתעלם ממנה. הוא המנהיג הטבעי של הכלבים הגדולים אצלנו, "המלך" של החצר, ומי ששומר בנאמנות (וקצת עקשנות) על האוכל ועל הסדר הטוב. ג''וניור הוא לא סתם כלב; הוא דמות דומיננטית עם אישיות כובשת של מנהיג אמיתי.

הדרך של ג''וניור לא הייתה קלה. הוא ננטש בינואר 2021 ומצא את עצמו סגור בין סורגי הכלוב. במהלך השנים הוא זכה לצאת לכמה בתים, אך בכל פעם מחדש הגורל התאכזר אליו והוא הוחזר לבית המחסה. לאחר הניסיונות האלו, ג''וניור הפך לדייר קבע אצלנו – הוא מצא בבית המחסה את הממלכה שלו, והוא מנהל אותה ביד רמה ובאהבה גדולה.

ג''וניור הוא דייר קבע בלב שלנו, והוא זקוק לתמיכה שלכם כדי להמשיך להנהיג את הלהקה בביטחון ובשובע. בחרו לתמוך במלך שלנו ולעזור לנו להעניק לו את החיים הטובים ביותר שמגיעים לו.','/assets/img/dog-junior-3.jpg',array['/assets/img/dog-junior-3.jpg','/assets/img/dog-junior-1.jpg','/assets/img/dog-junior-2.jpg','/assets/img/dog-junior-4.jpg']::text[],true,5);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('cooper','קופר','8 שנים','המנהיג של משפחת "הקופרים"','אם הייתם שואלים את קופר מה הדבר הכי חשוב בעולם, התשובה הייתה פשוטה: חיבוק. קופר הוא כלב גדול עם לב רחב אפילו יותר, מעין "דוב אכפת לי" ענק ומתוק שעבורו מגע חם הוא הדבר המשמעותי מכל.

את רוב חייו העביר קופר בכלבייה ברשפון, לשם הגיע עוד כשהיה גור. כשעבר אלינו יחד עם הלהקה שלו – "הקופרים" – גילינו כלב מקסים שפשוט אי אפשר שלא להתאהב בו. למרות שהוא המנהיג והמגן של החברים שלו, קופר ניחן ברגישות יוצאת דופן; הוא יודע להעניק חיבוק ונחמה אמיתית למתנדבים ולצוות בדיוק ברגעים שהם זקוקים לכך ביותר.

משפחה שלא מפרקים: הלהקה של קופר היא לא סתם קבוצת כלבים – הם המשפחה האמיתית אחד של השני. הכלבים כבר בני 8, ולאחר שנים של הישרדות משותפת, לא ניתן להפריד ביניהם. הם זקוקים לתמיכה שלכם כדי להמשיך לחיות יחד בביטחון, שכן הם יעבירו בבית המחסה את שארית חייהם כדיירי קבע אהובים.

בחרו לתמוך בקופר ובמשפחתו ועזרו לנו להעניק להם זקנה מכובדת, מלאה באהבה ובביטחון שהם לעולם לא יצטרכו להיפרד.','/assets/img/dog-cooper-1.jpg',array['/assets/img/dog-cooper-1.jpg','/assets/img/dog-cooper-2.jpg','/assets/img/dog-cooper-3.jpg']::text[],true,6);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('micha','מיכה','10 שנים','הלב הפועם וזקן השבט · בן 10','מיכה הוא הכלב הכי מבוגר בבית המחסה, בן 10, ומי שמכיר אותו יודע שהוא הלב הפועם של המקום. למרות כל מה שעבר בחייו, מיכה נשאר כלב מלא אהבה, ששום דבר לא משמח אותו יותר מאשר לקבל חופן נדיב של חטיפים ותשומת לב.

הסיפור של מיכה הוא סיפור של הישרדות בלתי רגילה. בשנת 2017, כשהיה רק בן שנה, הוא נלכד להסגר כשהוא סובל מאגן שבור – עדות כואבת להתעללות קשה שעבר. העמותה הצילה אותו, העניקה לו את הטיפול הרפואי המורכב שנדרש לו, והוא זכה לצאת למה שנראה כבית חם באומנה. אך הגורל התאכזר אליו שוב: שבע שנים לאחר מכן, מיכה נמצא משוטט לבדו ברחובות יפו, לאחר שהבעלים שלו פשוט נעלמה והשאירה אותו מאחור.

מיכה חזר הביתה, למקום שהציל אותו פעם אחת ולא יוותר עליו לעולם. בחרו לתמוך במיכה ולעזור לנו להעניק לו זקנה מכובדת, מלאה בחטיפים ובביטחון שהוא לעולם לא יינטש שוב.','/assets/img/dog-micha-1.jpg',array['/assets/img/dog-micha-1.jpg','/assets/img/dog-micha-2.jpg','/assets/img/dog-micha-3.jpg','/assets/img/dog-micha-4.jpg','/assets/img/dog-micha-5.jpg']::text[],true,7);
insert into public.dogs (slug,name,age_text,tagline,story,main_image,gallery,available_for_gift,sort) values ('bella','בלה','4 שנים','היופי השועלי שמחכה לשוב הביתה','בלה היא כלבה שפשוט יודעת שהיא מיוחדת. עם המראה השועלי והחום שלה, היא דואגת להראות לכולם כמה היא יפה, ואין מתנדב בבית המחסה שלא מתאהב בקסם שלה ממבט ראשון. היא מקסימה, חברותית וניכר שהיא רגילה לחום של בני אדם.

אבל מאחורי המראה הכובש מסתתר סיפור שובר לב. במאי 2025, אחרי 3 שנים שבהן חיה בתוך בית והייתה חלק ממשפחה, בלה ננטשה. המעבר מהספה המוכרת לבית המחסה היה לה קשה מנשוא. במשך תקופה ארוכה, בכל בוקר מחדש, בלה הייתה מתייצבת ליד השער ומחכה – מביטה החוצה בתקווה שהאנשים שהכירה יבואו לקחת אותה חזרה.

בלה עדיין מחכה לבית שיבין שכלב הוא בן משפחה לכל החיים. בחרו לתמוך בבלה ועזרו לנו להעניק לה את הטיפול והפינוק שמגיעים לה, עד שתמצא את הלב שייפתח עבורה שוב.','/assets/img/dog-bella-3.jpg',array['/assets/img/dog-bella-3.jpg','/assets/img/dog-bella-1.jpg','/assets/img/dog-bella-2.jpg','/assets/img/dog-bella-4.jpg','/assets/img/dog-bella-5.jpg']::text[],false,8);
