insert into public.fallen (slug,card_title,modal_title,eyebrow,card_text,story_html,hero_image,grow_link,sort) values ('adi','פרויקט הנצחה לזכרו של סמ"ר עדי צור ז"ל','פרויקט הנצחה לזכרו של סמ"ר עדי צור ז"ל — גיבור ישראל','מנציחים ומצילים · לזכרם','גיבור ישראל שהגן בגופו על קיבוץ כיסופים ב־7 באוקטובר.','<img class="memorial-hero-img" src="/assets/img/memorial-adi-2.jpg" alt="סמ&quot;ר עדי צור ז&quot;ל">
    <p>עדי צור היה לוחם עם נשמה גדולה ואומץ לב עילאי. ב־7 באוקטובר 2023 הגן עדי בגופו על קיבוץ כיסופים בקרב גבורה מול עשרות מחבלים. במעשיו הציל עדי חיים של אנשים רבים, כשהוא מפגין גבורה בלתי רגילה עד נשימתו האחרונה. אך מעבר להיותו לוחם אמיץ, עדי היה אדם שראה את הנשמות השקופות ביותר — אלו שזקוקות לחמלה ולסבלנות.</p>
    <p><strong>הבחירה בלני: סיפור על סבלנות ואהבה.</strong> החיבור בין עדי לעמותת "חיים של אחרים" נרקם דרך לני, כלבה שעברה התעללות קשה וחיכתה שנים ארוכות בבית המחסה שמישהו יפתח לה את הלב. לני הייתה כלבה מפוחדת, כזו שאיש לא העז להתקרב אליה — אבל עדי בחר בה דווקא בגלל הקושי שלה. בסבלנות של מלאך ובאהבה אינסופית הוא שיקם אותה והעניק לה ביטחון שמעולם לא ידעה.</p>
    <p><strong>המשכיות של אור בבית משפחת צור.</strong> לאחר שעדי נפל, לני נותרה עם חלל עצום בלב. בצעד מרגש מאין כמוהו בחרו הוריו של עדי לאמץ את לני אליהם הביתה. היום לני חיה בחיבוק העוטף של משפחת צור — היא הנחמה שלהם והם הביטחון שלה. היא זיכרון חי ופועם לאהבה של עדי, ומימוש הצוואה הלא כתובה שלו: לעזור למי שקשה לו יותר מכולם.</p>
    <p>פרויקט ההנצחה שהוקם לזכרו הוא המקום שבו המורשת של עדי ממשיכה לחיות. כאן אנחנו מעניקים תקווה לכלבים שאיש לא רצה, מתוך אמונה שבדיוק כמו לני — לכל נשמה מגיע "גיבור" שיאמין בה.</p>','/assets/img/memorial-adi-leni.jpg','https://pay.grow.link/NzMwNzY~18956d40360336e249b131564b23c5a1-Mzg0MjI5Mg',0);
insert into public.fallen (slug,card_title,modal_title,eyebrow,card_text,story_html,hero_image,grow_link,sort) values ('shani','פרויקט הנצחה לזכרה של שני גבאי ז"ל','פרויקט הנצחה לזכרה של שני גבאי ז"ל — האור שממשיך להציל חיים','מנציחים ומצילים · לזכרם','קרן אור של חמלה שנרצחה במסיבת הנובה ברעים.','<img class="memorial-hero-img" src="/assets/img/memorial-shani-2.jpg" alt="שני גבאי ז&quot;ל">
    <p>שני גבאי הייתה קרן אור של חמלה וחיוך שלא נגמר. ב־7 באוקטובר 2023 נרצחה שני במסיבת ה"נובה" ברעים, לאחר שעות ארוכות שבהן ניסתה להציל אחרים ולהימלט. שני הייתה רק בת 26 — צעירה מלאת חיים עם לב ענק שתמיד היה פתוח ליצורים החלשים ביותר: הכלבים הנטושים.</p>
    <p><strong>החלום של שני והלב שנשאר עם המשפחה.</strong> בחייה, שני לא רק אהבה כלבים — היא חיה אותם. היא התנדבה, הצילה כלבים מהרחוב ודאגה לכל נשמה על ארבע שנקלעה בדרכה. הכלבים האישיים של שני היו עבורה בני משפחה לכל דבר, העוגן והשמחה שלה בכל יום. לאחר לכתה, בצעד שכולו אהבה והמשכיות, אימצו הוריה את הכלבים שלה. היום הכלבים ששני כל כך אהבה וטיפחה חיים בחיק משפחתה — הם הנחמה הגדולה ביותר של הוריה, זיכרון חי ונושם לאהבה האינסופית שלה.</p>
    <p><strong>ממשיכים את הדרך של שני.</strong> החלום הגדול של שני, זה שדיברה עליו תמיד, היה להקים בית מחסה משלה — מקום שבו כלבים יוכלו להשתקם, לרוץ חופשי ולהרגיש נאהבים באמת. כדי להגשים את החלום ששני לא הספיקה לממש, הקימה עמותת "חיים של אחרים" את "פרויקט הנצחה לזכרה של שני גבאי".</p>
    <p>זהו פרויקט של תקווה, שבו הרוח של שני — רוח של נתינה ללא תנאי ושמחת חיים — פועמת בכל זנב שמכשכש. שני האמינה שלכל כלב מגיע סיכוי, ואנחנו כאן כדי לוודא שהסיכוי הזה יתממש. בכל פעם שכלב מהבית שלנו מוצא משפחה, אנחנו יודעים ששני מחייכת מלמעלה — כי החלום שלה ממשיך לחיות כאן, אצלנו, בכל יום מחדש.</p>','/assets/img/memorial-shani-alpha.jpg','https://pay.grow.link/NzMwNzY~f75305ca1aba6a0174e2817e1fb4d7f6-Mzg0MjI4Ng',1);
insert into public.fallen (slug,card_title,modal_title,eyebrow,card_text,story_html,hero_image,grow_link,sort) values ('yair','פרויקט הנצחה לזכרו של יאיר כץ ז"ל','פרויקט הנצחה לזכרו של יאיר כץ ז"ל — הלב הפועם שלנו','מנציחים ומצילים · לזכרם','גם מהשטח בעזה לא שכח יאיר את הנשמות האבודות.','<img class="memorial-hero-img" src="/assets/img/memorial-yair-bruce.jpg" alt="יאיר כץ ז&quot;ל עם ברוס">
    <p><strong>הניצוץ של יאיר: חמלה שחוצה גבולות ומרחקים.</strong> יאיר כץ ז"ל נשא בתוכו אהבה אינסופית לכלבים, אהבה שלא כבתה גם ברגעים המאתגרים ביותר. טלי, מנהלת העמותה, מספרת שגם מהשטח בעזה יאיר לא שכח את הנשמות האבודות שפגש בדרך. הוא יצר קשר עם טלי וביקש את עזרתה כדי להושיט יד לכלבים חסרי אונים שנותרו ללא מחסה בין ההריסות. בשיתוף פעולה מרגש, טלי עזרה להציל את אותם כלבים שיאיר פגש, והעניקה להם את הביטחון שכל כך היו זקוקים לו. זו הייתה המהות של יאיר: לראות את האור ואת הצורך בעזרה בכל מקום שבו דרכו רגליו.</p>
    <p><strong>הלב של ברוס: מבית המחסה אל חיבוק של משפחה.</strong> סיפורו של ברוס, כלב הפיטבול האהוב, הוא עדות חיה לקשר העמוק שבין יאיר לעמותת "חיים של אחרים". ברוס היה דייר ותיק בבית המחסה — כלב גדול עם לב זהב שחיכה שנים ארוכות שמישהו יראה את יופיו הפנימי מעבר לסטיגמות. יאיר היה המאמץ שלו: זה שפתח את הלב והפך לחברו הטוב ביותר.</p>
    <p>לאחר נפילתו של יאיר, ברוס לא נותר לבד. בצעד מרגש שסגר מעגל של חסד, אחיו של יאיר בחר להמשיך את דרכו ואימץ את ברוס אליו. היום ברוס הוא הרבה יותר מכלב מאומץ — הוא זיכרון חי, נושם ומכשכש בזנב ליאיר. הוא מזכיר לכולנו שאהבה אמיתית אינה נגמרת: היא עוברת הלאה, מהאח שנפל אל האח שממשיך את דרכו, בתוך משפחה שעוטפת אותו בחום ובנחמה.</p>
    <p>בית המחסה שלנו הוא הבית של יאיר — מקום שבו כל כלב מקבל הזדמנות שנייה, בדיוק כפי שיאיר העניק לברוס.</p>','/assets/img/memorial-yair-bruce.jpg','https://pay.grow.link/NzMwNzY~e559cf60c4fbcd87718be66364ec6495-Mzg0MjI5Nw',2);
